import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.
export const STATUS_QUERY = gql(`
  query classradarStatus {
    classradarStatus {
      plugin
      version
      subdomain
      userId
      userEmail
    }
  }
`);

export const CLASS_RADAR_QUERY = gql(`
  query classradarDashboard($classCode: String!) {
    classradarStatus {
      userEmail
    }
    classradarSeats(classCode: $classCode) {
      seat
      studentEmail
      name
      status
      errorMinutes
      errorTitle
      errorMessage
      errorFile
      errorLine
      hintsUsed
      understood
    }
    classradarTopErrors(classCode: $classCode) {
      normalizedKey
      title
      count
      sampleMessage
    }
  }
`);

export const INTERVIEW_FEEDBACK_MUTATION = gql(`
  mutation classradarInterviewFeedback($question: String!, $answer: String!) {
    classradarInterviewFeedback(question: $question, answer: $answer) {
      score
      good
      improve
      source
    }
  }
`);
